import ReactDOM from "react-dom";
import {
  createPasteEvent,
  GlobalTestState,
  render,
  waitFor,
} from "./test-utils";
import { UI, Pointer } from "./helpers/ui";
import { API } from "./helpers/api";
import { actionFlipHorizontal, actionFlipVertical } from "../actions";
import { getElementAbsoluteCoords } from "../element";
import {
  ExcalidrawElement,
  ExcalidrawImageElement,
  ExcalidrawLinearElement,
  FileId,
} from "../element/types";
import { newLinearElement } from "../element";
import ExcalidrawApp from "../excalidraw-app";
import { mutateElement } from "../element/mutateElement";
import { NormalizedZoomValue } from "../types";
import { ROUNDNESS } from "../constants";

const { h } = window;

const mouse = new Pointer("mouse");
jest.mock("../data/blob", () => {
  const originalModule = jest.requireActual("../data/blob");

  //Prevent Node.js modules errors (document is not defined etc...)
  return {
    __esModule: true,
    ...originalModule,
    resizeImageFile: (imageFile: File) => imageFile,
    generateIdFromFile: () => "fileId" as FileId,
  };
});
beforeEach(async () => {
  // Unmount ReactDOM from root
  ReactDOM.unmountComponentAtNode(document.getElementById("root")!);

  mouse.reset();
  localStorage.clear();
  sessionStorage.clear();
  jest.clearAllMocks();

  Object.assign(document, {
    elementFromPoint: () => GlobalTestState.canvas,
  });
  await render(<ExcalidrawApp />);
  h.setState({
    zoom: {
      value: 1 as NormalizedZoomValue,
    },
  });
});

const createAndSelectOneRectangle = (angle: number = 0) => {
